dtsPropsFor.HueView:
lights: { id: string; name: string; /** room name, null = no room */ room: string | null; on: boolean; /** 0–100, null if not dimmable */ brightness: number | null }[];
  /** light id currently being switched (disables its switch) */ busyId?: string | null;
  /** omit to render read-only switches */ onToggle?: (light: { id: string; name: string; /** room name, null = no room */ room: string | null; on: boolean; /** 0–100, null if not dimmable */ brightness: number | null }) => void;
  /** rooms/zones/whole home – renders on/off buttons per group and «Slå av/på alle» for kind "home" */ groups?: { id: string; name: string; kind: 'home' | 'room' | 'zone'; on: boolean; lights: number; resourceId: string | null; brightness: number | null }[];
  onGroup?: (group: { id: string; name: string; kind: 'home' | 'room' | 'zone'; on: boolean; lights: number; resourceId: string | null; brightness: number | null }, on: boolean) => void;
  /** shows a pencil to rename a light (Hue max 32 chars) */ onRenameLight?: (light: { id: string; name: string }, name: string) => void;
  /** shows a pencil on room headings to rename the room */ onRenameGroup?: (group: { id: string; name: string; kind: 'home' | 'room' | 'zone'; resourceId: string | null; brightness: number | null }, name: string) => void;
  /** room names expanded initially (rooms are collapsible rows) */ defaultOpen?: string[];
  /** shows a bulb button per light that makes it blink (Hue identify) */ onIdentify?: (light: { id: string; name: string }) => void;
  /** brightness slider per light (1–100, sent on release) */ onDimLight?: (light: { id: string; name: string }, brightness: number) => void;
  /** brightness slider for a whole room, shown when the room is expanded */ onDimGroup?: (group: { id: string; name: string }, brightness: number) => void;

